#!/usr/bin/env bash
# install-mrmodel-skill.sh — 一行命令安装 mr-model skill (零依赖, 零额外操作)
#
# 用户/agent 跑这一行就完事:
#   curl -sL https://raw.githubusercontent.com/Cesario-Lzc/M-Model/main/install-mrmodel-skill.sh | bash
#   备用镜像 (CDN 缓存可能滞后, 安装异常时改用上面的 raw 地址):
#     curl -sL https://cdn.jsdelivr.net/gh/Cesario-Lzc/M-Model@main/install-mrmodel-skill.sh | bash
#
# 行为:
#   1. 建目录 (~/.claude/skills/mr-model, 可用 env MRMODEL_SKILL_DIR 改)
#   2. 写入 SKILL.md + OUTPUT-REFERENCE.md 双文件 (v1.5.2 起):
#      CDN 直拉为主 (jsdelivr 主 / raw 备) + 内嵌副本 sha256 校验
#      → 失败 fallback 内嵌 base64 (零外部依赖); 顺手清旧版 manifest.json 残留
#   3. 提示输 token (或读 env MR_MCP_TOKEN / 已有 ~/.config/mrmodel/token)
#   4. 把客户端版本 X-Skill-Version 写进 MCP 配置 (详见 SKILL.md §7)
#   5. healthz 探活 + tools/list 鉴权验证 (0 配额)

set -euo pipefail

# ===== 颜色 =====
RED='\033[0;31m'; GRN='\033[0;32m'; YLW='\033[1;33m'; NC='\033[0m'
info()  { echo -e "${GRN}[✓]${NC} $*"; }
warn()  { echo -e "${YLW}[!]${NC} $*"; }
err()   { echo -e "${RED}[✗]${NC} $*" >&2; }

# ===== 路径 =====
# 探测 ~/.claude / ~/.workbuddy → 默认 Claude Code
detect_skill_dir() {
    if [ -d "$HOME/.claude" ]; then
        echo "$HOME/.claude/skills/mr-model"
    elif [ -d "$HOME/.workbuddy" ]; then
        echo "$HOME/.workbuddy/skills/mr-model"
    else
        echo "$HOME/.claude/skills/mr-model"
    fi
}
TARGET_SKILL_DIR="${MRMODEL_SKILL_DIR:-$(detect_skill_dir)}"
TARGET_TOKEN_FILE="${MRMODEL_TOKEN_FILE:-$HOME/.config/mrmodel/token}"
MCP_URL="${MRMODEL_MCP_URL:-https://mcp.cesario.top}"

echo "=================================================="
echo "  mr-model skill 一键安装 (一行命令版)"
echo "=================================================="
echo "目标: $TARGET_SKILL_DIR"
echo "MCP:  $MCP_URL"
echo ""

# ===== Step 1: 目录 =====
info "Step 1/5 建目录"
mkdir -p "$TARGET_SKILL_DIR"
mkdir -p "$(dirname "$TARGET_TOKEN_FILE")"
chmod 700 "$(dirname "$TARGET_TOKEN_FILE")"
info "  $TARGET_SKILL_DIR"
info "  $(dirname "$TARGET_TOKEN_FILE") (700)"

# ===== Step 2: 写入 SKILL.md =====
info "Step 2/5 写入 skill 文件"
# sha 工具 mac(shasum)/linux(sha256sum) 兼容 (旧写法 `shasum || sha256sum` 在 linux 上
# awk 空输出退出码 0, || 不触发, CDN 校验全废 — 2026-09-15 治本)
_sha256() {
    if command -v shasum >/dev/null 2>&1; then shasum -a 256 "$1" | awk '{print $1}'
    else sha256sum "$1" | awk '{print $1}'; fi
}


# 源优先级: CDN 直拉 > 内嵌 base64
if [ -n "${MRMODEL_SKILL_SRC_DIR:-}" ] && [ -f "$MRMODEL_SKILL_SRC_DIR/SKILL.md" ]; then
    warn "  源: env 目录 $MRMODEL_SKILL_SRC_DIR (本地升级模式)"
    install -m 644 "$MRMODEL_SKILL_SRC_DIR/SKILL.md" "$TARGET_SKILL_DIR/SKILL.md"
    [ -f "$MRMODEL_SKILL_SRC_DIR/OUTPUT-REFERENCE.md" ] && \
        install -m 644 "$MRMODEL_SKILL_SRC_DIR/OUTPUT-REFERENCE.md" "$TARGET_SKILL_DIR/OUTPUT-REFERENCE.md"
elif [ -n "${1:-}" ] && [ -f "$1" ]; then
    warn "  源: 外部参数 $1"
    install -m 644 "$1" "$TARGET_SKILL_DIR/SKILL.md"
    [ -f "$(dirname "$1")/OUTPUT-REFERENCE.md" ] && \
        install -m 644 "$(dirname "$1")/OUTPUT-REFERENCE.md" "$TARGET_SKILL_DIR/OUTPUT-REFERENCE.md"
else
    # CDN 直拉为主 (jsdelivr 主 / raw 备)
    CDN_BASE="${MRMODEL_CDN_BASE:-https://cdn.jsdelivr.net/gh/Cesario-Lzc/M-Model@main}"
    RAW_BASE="${MRMODEL_RAW_BASE:-https://raw.githubusercontent.com/Cesario-Lzc/M-Model/main}"
    # 内嵌副本先落盘 (已知好版, 兼作 CDN 拉取的 sha256 校验参照)
    echo '' | base64 -d > /tmp/mrmodel_embed.md
    echo '' | base64 -d > /tmp/mrmodel_ref_embed.md
    # CDN 直拉双文件 (v1.5.2): jsdelivr 主 / raw 备, sha 与内嵌一致才装 (防 CDN 旧版);
    # 失败 fallback 内嵌 base64。
    fetch_install() {
        # $1=远端文件名 $2=临时文件 $3=内嵌副本 $4=目标路径
        local fname="$1" tmp="$2" embed="$3" dest="$4" want got ok=0
        want=$(_sha256 "$embed")
        for BASE in "$CDN_BASE" "$RAW_BASE"; do
            if curl -fsSL --max-time 15 "$BASE/$fname" -o "$tmp" 2>/dev/null \
               && head -c 10 "$tmp" | grep -q '^---\|^#'; then
                got=$(_sha256 "$tmp")
                if [ -n "$got" ] && [ "$got" = "$want" ]; then
                    install -m 644 "$tmp" "$dest"
                    ok=1
                    break
                else
                    warn "  $BASE/$fname 版本落后 (sha ${got:0:8} != 内嵌 ${want:0:8}), 换下一源/fallback"
                fi
            fi
        done
        rm -f "$tmp"
        if [ "$ok" = "1" ]; then
            info "  $fname: CDN 直拉 — 与远端实时一致"
        else
            warn "  $fname: CDN 直拉失败, fallback 内嵌 base64 (随脚本打包, 可能非最新)"
            install -m 644 "$embed" "$dest"
        fi
    }
    fetch_install "SKILL.md" /tmp/mrmodel_skill_md.tmp /tmp/mrmodel_embed.md "$TARGET_SKILL_DIR/SKILL.md"
    fetch_install "OUTPUT-REFERENCE.md" /tmp/mrmodel_ref_md.tmp /tmp/mrmodel_ref_embed.md "$TARGET_SKILL_DIR/OUTPUT-REFERENCE.md"
    rm -f /tmp/mrmodel_embed.md /tmp/mrmodel_ref_embed.md
fi
chmod 644 "$TARGET_SKILL_DIR/SKILL.md"
rm -f "$TARGET_SKILL_DIR/manifest.json"   # v1.4.4 起 manifest 下线, 清旧装机残留

SKILL_SHA=$(_sha256 "$TARGET_SKILL_DIR/SKILL.md" 2>/dev/null)
info "  SKILL.md sha256: ${SKILL_SHA:0:16}..."
[ -f "$TARGET_SKILL_DIR/OUTPUT-REFERENCE.md" ] && info "  OUTPUT-REFERENCE.md sha256: $(_sha256 "$TARGET_SKILL_DIR/OUTPUT-REFERENCE.md" | cut -c1-16)..."

# ===== Step 3: token =====
info "Step 3/5 配置 token"

if [ -n "${MR_MCP_TOKEN:-}" ]; then
    TOKEN="$MR_MCP_TOKEN"
    info "  来源: env MR_MCP_TOKEN (${#TOKEN} 字符)"
elif [ -f "$TARGET_TOKEN_FILE" ]; then
    warn "  已存在 token 文件, 跳过 (如需重设先 rm $TARGET_TOKEN_FILE)"
    TOKEN=$(cat "$TARGET_TOKEN_FILE")
else
    echo ""
    echo "  请输入 mcp token (格式: mcp_live_<48hex> = 57 字符):"
    echo "  生成: https://mrmodel.cesario.top/mcp-tokens 页"
    echo "  提示: 任意已生效的 MCP token 都行, 多设备可共用同一个"
    echo ""
    read -r -p "  token: " TOKEN
    [ -z "$TOKEN" ] && { err "token 必填, 退出"; exit 1; }
    if ! echo "$TOKEN" | grep -qE '^mcp_live_[0-9a-f]{48}$'; then
        warn "  token 格式不标准 (期望: mcp_live_<48hex>), 仍写入"
    fi
fi

echo -n "$TOKEN" > "$TARGET_TOKEN_FILE"
chmod 600 "$TARGET_TOKEN_FILE"
info "  token 写入 $TARGET_TOKEN_FILE (600)"

# ===== Step 4: 写 MCP 配置版本标识 =====
# 版本号从刚落盘的 SKILL.md frontmatter 读。
SKILL_VERSION=$(grep -m1 '^version:' "$TARGET_SKILL_DIR/SKILL.md" 2>/dev/null | awk '{print $2}' | tr -d '[:space:]')
[ -z "$SKILL_VERSION" ] && SKILL_VERSION="1.4.0"   # frontmatter 读不出时的兜底
info "Step 4/5 写入 MCP 配置版本标识 (X-Skill-Version: $SKILL_VERSION)"

PATCH_OUT=$(SKILL_VERSION="$SKILL_VERSION" MCP_HOST="${MCP_URL#https://}" MCP_TOKEN="$TOKEN" python3 - <<'PYEOF' || echo "  [异常] 未能自动写入, 请手工添加 X-Skill-Version"
import json
import os
import shutil

HEADER = "X-Skill-Version"
VER = os.environ.get("SKILL_VERSION", "")
HOST = os.environ.get("MCP_HOST", "mcp.cesario.top")

# 候选位置覆盖主流 MCP 宿主; 找不到就降级为手工指引, 不猜更多路径。
CANDIDATES = [
    os.path.expanduser("~/.workbuddy/mcp.json"),
    os.path.expanduser("~/.claude.json"),
    os.path.expanduser("~/.claude/mcp.json"),
    os.path.expanduser("~/.codebuddy/mcp.json"),
    os.path.expanduser("~/.cursor/mcp.json"),
    os.path.expanduser("~/Library/Application Support/Claude/claude_desktop_config.json"),
]


def iter_server_dicts(node):
    """递归产出所有 mcpServers 字典。
    Claude Code 的 ~/.claude.json 结构特殊: mcpServers 可能嵌在 projects.<cwd> 下,
    只扫顶层会静默漏配, 必须递归。"""
    if isinstance(node, dict):
        for k, v in node.items():
            if k == "mcpServers" and isinstance(v, dict):
                yield v
            for found in iter_server_dicts(v):
                yield found
    elif isinstance(node, list):
        for item in node:
            for found in iter_server_dicts(item):
                yield found


def _write_new_entry(path, cfg, token):
    """往 cfg 的顶层 mcpServers 写/补全 mr-model 条目，.bak 备份后落盘。
    已有 mr-model 条目时只补 headers，url 不动（防覆盖用户自定义）。"""
    servers = cfg.setdefault("mcpServers", {})
    srv = servers.get("mr-model")
    if not isinstance(srv, dict):
        srv = {}
        servers["mr-model"] = srv
    srv.setdefault("url", "https://%s/mcp" % HOST)
    headers = srv.get("headers")
    if not isinstance(headers, dict):
        headers = {}
        srv["headers"] = headers
    headers["Authorization"] = "Bearer " + token
    headers[HEADER] = VER
    if os.path.isfile(path):
        shutil.copy2(path, path + ".bak")
    else:
        parent = os.path.dirname(path)
        if parent and not os.path.isdir(parent):
            os.makedirs(parent, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(cfg, f, ensure_ascii=False, indent=2)
    print("  [已创建] %s 里的 mr-model 条目 (原文件备份为 %s.bak)" % (path, path))


def main():
    patched, already_ok = [], []

    for path in CANDIDATES:
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r", encoding="utf-8") as f:
                cfg = json.load(f)
        except Exception as e:
            # 配置文件里躺着 token, 写坏 = 用户服务直接不可用。
            # 故只用 json 模块读写, 绝不 sed/正则硬改; 解析失败就原样放过让用户自己处理。
            print("  [跳过] %s 解析失败 (%s)" % (path, type(e).__name__))
            continue

        changed = False
        up_to_date = False
        for servers in iter_server_dicts(cfg):
            for name, srv in servers.items():
                if not isinstance(srv, dict):
                    continue
                url = srv.get("url") or ""
                if not (isinstance(url, str) and HOST in url):
                    continue          # 不是本服务的条目, 一个字符都不许动
                headers = srv.get("headers")
                if not isinstance(headers, dict):
                    headers = {}
                    srv["headers"] = headers
                if headers.get(HEADER) == VER:
                    up_to_date = True
                else:
                    headers[HEADER] = VER
                    changed = True

        if changed:
            try:
                shutil.copy2(path, path + ".bak")
                with open(path, "w", encoding="utf-8") as f:
                    json.dump(cfg, f, ensure_ascii=False, indent=2)
                patched.append(path)
            except Exception as e:
                print("  [失败] %s 写回失败 (%s: %s)" % (path, type(e).__name__, e))
        elif up_to_date:
            already_ok.append(path)

    if patched:
        for p in patched:
            print("  [已写入] %s  (原文件备份为 %s.bak)" % (p, p))
    elif already_ok:
        print("  [无需修改] 配置里已是最新版本标识")
    else:
        # 新装用户：任何候选配置都没有本服务条目 → 自动创建 mr-model 条目
        # （json 模块读写 + .bak 备份，与 patch 同一安全姿势；token 走 env 不落日志）
        token = os.environ.get("MCP_TOKEN", "")
        if not token:
            print("  [跳过] 未读到 token, 请手动在 mcpServers.mr-model 配置 url + headers")
            return
        created = False
        for path in CANDIDATES:
            if not os.path.isfile(path):
                continue
            try:
                with open(path, "r", encoding="utf-8") as f:
                    cfg = json.load(f)
                if not isinstance(cfg, dict):
                    continue
            except Exception as e:
                print("  [跳过] %s 解析失败 (%s)" % (path, type(e).__name__))
                continue
            try:
                _write_new_entry(path, cfg, token)
                created = True
            except Exception as e:
                print("  [失败] %s 写回失败 (%s: %s)" % (path, type(e).__name__, e))
            break
        if not created:
            # 候选全不存在 → 新建 ~/.claude.json（首次装 MCP 的极简用户）
            try:
                _write_new_entry(os.path.expanduser("~/.claude.json"), {}, token)
                created = True
            except Exception as e:
                print("  [失败] ~/.claude.json 创建失败 (%s: %s)" % (type(e).__name__, e))
        if not created:
            print('  请手动在 mcpServers.mr-model.headers 里加一行: "%s": "%s"' % (HEADER, VER))
            print("  常见位置: ~/.workbuddy/mcp.json 或 ~/.claude.json")


main()
PYEOF
)
echo "$PATCH_OUT"

# ===== Step 5: 探活 + 鉴权 =====
info "Step 5/5 验证 MCP 端点 + 鉴权"
HTTP_CODE=$(curl -sS -o /tmp/healthz.json -w "%{http_code}" "$MCP_URL/healthz" --max-time 10 || echo "000")
if [ "$HTTP_CODE" = "200" ]; then
    DB_OK=$(python3 -c "import json; print(json.load(open('/tmp/healthz.json')).get('db_ok','?'))" 2>/dev/null || echo "?")
    info "  healthz: 200 db_ok=$DB_OK"
else
    err "  healthz 返 $HTTP_CODE, MCP 端不可达"
    err "  (脚本已装文件, token 已配, MCP 通了就能用)"
fi

# tools/list 鉴权
RESP=$(curl -sS -X POST "$MCP_URL/mcp" \
    -H "Authorization: Bearer $TOKEN" \
    -H "X-Skill-Version: $SKILL_VERSION" \
    -H "Content-Type: application/json" \
    -H "Accept: application/json, text/event-stream" \
    -d '{"jsonrpc":"2.0","id":1,"method":"tools/list"}' \
    --max-time 10 || echo "CURL_FAILED")

if echo "$RESP" | grep -q '"name":"query_video_list"'; then
    TOOL_COUNT=$(echo "$RESP" | grep -oE '"name":"[a-z_]+"' | wc -l | tr -d ' ')
    info "  鉴权通过, $TOOL_COUNT tool 全可见"
else
    err "  鉴权失败, 响应:"
    echo "$RESP" | head -c 500
    echo ""
    warn "  请检查: ① token 是否有效 ② mcp-tokens 页 status=active ③ 配额是否打爆"
fi

echo ""
echo "=================================================="
echo "  ✅ 装好了！打开 Claude Code 直接用人话问，比如："
echo "    ① 模型先生，最近有什么视频？"
echo "    ② 中际旭创最近被怎么看？给的理由是什么？"
echo "    ③ 给我出一份今天的晨报，带多空方向和评论区热词"
echo "=================================================="
echo ""
echo "卸载: rm -rf $TARGET_SKILL_DIR $TARGET_TOKEN_FILE  # 当前宿主: $TARGET_SKILL_DIR"
echo "升级: 重跑本行命令 (覆盖 SKILL.md, 内嵌副本 sha256 校验)"
